import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const ev = ex.event() || {};
  const problemId =
    ev["display_id"] ||
    ev["problem.id"] ||
    ev["event.id"] ||
    ev.pid ||
    "unknown-problem";
  return {
    problemId,
    dedupKey: "dt-problem-" + problemId,
    closeNotes: "Resolved automatically: Dynatrace Problem closed (" + problemId + ")"
  };
}

import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const p = await ex.result("prepare-close-ids");
  const pdKey = "__PD_ROUTING_KEY__";

  const pdRes = await fetch("https://events.pagerduty.com/v2/enqueue", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      routing_key: pdKey,
      event_action: "resolve",
      dedup_key: p.dedupKey
    })
  });
  const pdText = await pdRes.text();
  if (!pdRes.ok) throw new Error("PD resolve failed: " + pdText);
  return { problemId: p.problemId, dedupKey: p.dedupKey, pagerduty: pdText };
}
